let person=0,step=0,timer=null,geo=null,mediaMode="film";const $=id=>document.getElementById(id);const sources=[['河流湖泊：Natural Earth','https://www.naturalearthdata.com/downloads/10m-physical-vectors/10m-rivers-lake-centerlines/'],['Natural Earth 公版许可','https://www.naturalearthdata.com/about/terms-of-use/'],['初中2025课标公开版',curriculumSources.junior.url],['高中2025课标公开版',curriculumSources.high.url],['参考项目：江山时序','https://github.com/DeanChensj/jiangshan-map'],['古诗文网：诗文原文与创作背景','https://www.gushiwen.cn/'],['维基文库：古典诗词原典','https://zh.wikisource.org/'],['中华诗词网：《定风波》与题注','https://www.zhsc.org/work/work-1a16de8c10428a1420d837cd481eac46.htm'],['苏东坡专题：黄州五年','https://www.sudongpo.org/huang-zhou-wu-nian/'],['荆门山地望：云上宜都','https://cjy.hbyidu.com.cn/p/6795.html'],['地理底图：DataV 中国省级 GeoJSON','https://geo.datav.aliyun.com/areas_v3/bound/100000_full.json']];
function showModal(html){if($('poetryPlayer'))$('poetryPlayer').pause();$('modalBody').innerHTML=html;$('modal').showModal();$('modal').scrollTop=0}
function currentPhoto(){if(['诗中地点','地点待考'].includes(people[person].stops[step][11].role))return null;return sitePhotos[{'庐山':'lushan','黄鹤楼':'huanghe','白帝城':'baidi','成都':'dufu','杭州':'xihu'}[people[person].stops[step][1]]]}
function photoCredit(p){return `<a href="${p.source}" target="_blank" rel="noopener noreferrer">${p.author} · 维基共享资源 ↗</a> · <a href="${p.licenseUrl}" target="_blank" rel="noopener noreferrer">${p.license}</a>`}
function media(){const p=currentPhoto(),f=poetryFilms.find(f=>f.poemId===people[person].stops[step][11].id);if(!p&&!f)return '';const showFilm=f&&(!p||mediaMode!=='photo');return `${p&&f?`<div class="media-tabs" role="group" aria-label="画面类型"><button id="filmTab" aria-pressed="${!!showFilm}">▶ 朗诵影片</button><button id="photoTab" aria-pressed="${!showFilm}">▧ 实景照片</button></div>`:''}${showFilm?`<figure class="visit-film"><button class="film-cover" id="detailFilm" data-film="${f.id}" aria-label="播放${f.title}朗诵影片"><img src="assets/films/${f.id}-poster.jpg" alt="${f.title}朗诵影片封面" width="1280" height="720"><span class="film-play">▶</span><span class="film-duration">${filmDuration(f.duration)}</span></button><figcaption><strong>${f.title} · 朗诵影片</strong><span>点击播放 · 中文朗诵、配乐与逐句字幕</span></figcaption></figure>`:`<figure class="site-photo"><button id="enlargePhoto" aria-label="放大${p.title}照片"><img src="${p.src}" alt="${p.title}实景照片" width="1280" height="853"><span>⤢ 点击看大图</span></button><figcaption><strong>${p.title}</strong><span>拍摄于 ${p.date} · 非实时影像</span><small>${photoCredit(p)}<br>适配展示，点击可看完整构图。</small></figcaption></figure><p class="photo-note">${p.note}</p>`}`}
function enlargePhoto(){const p=currentPhoto();showModal(`<h2>${p.title}</h2><img class="large-photo" src="${p.src}" alt="${p.title}完整照片"><p>拍摄于 ${p.date} · ${photoCredit(p)}</p><p>${p.note}</p>`)}
function render(){const p=people[person],s=p.stops[step],m=s[11];$('people').innerHTML=people.map((x,i)=>`<button class="person ${i===person?'selected':''}" data-person="${i}" aria-pressed="${i===person}"><span class="portrait">${x.name[0]}</span><span><strong>${x.name}</strong><small>${i===2?'北宋':'唐'} · ${x.stops.length} 篇</small></span><em>${i===person?'●':'○'}</em></button>`).join('');document.querySelectorAll('[data-person]').forEach(el=>el.onclick=()=>{stop();person=+el.dataset.person;step=0;mediaMode='film';render()});$('bio').innerHTML=`<h3>${p.title}</h3><p>${p.desc}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><button class="author-library" id="authorLibrary">查看${p.name}全部 ${p.stops.length} 篇 →</button>`;$('authorLibrary').onclick=()=>{location.href='library.html?author='+person;};$('mapTitle').textContent=p.name+'的山河行旅';$('mapQuote').textContent=m.role==='地点待考'?'地点待考 · 先读诗，再寻迹':p.quote;$('timeTitle').textContent=s[0]+' · '+s[1];$('timeSubtitle').textContent=s[5];$('progress').textContent=`第 ${step+1} 篇 / 共 ${p.stops.length} 篇`;$('range').max=p.stops.length-1;$('range').value=step;
const tickIds=[0,step,p.stops.length-1].filter((n,i,arr)=>arr.indexOf(n)===i).sort((a,b)=>a-b);$('ticks').innerHTML=tickIds.map(i=>`<button data-tick="${i}" class="${i===step?'selected-tick':''}">${p.stops[i][0]}<br>${p.stops[i][1]}</button>`).join('');document.querySelectorAll('[data-tick]').forEach(el=>el.onclick=()=>select(+el.dataset.tick));
const related=p.stops.map((v,i)=>({v,i})).filter(({v})=>v[1]===s[1]);$('stationWorks').innerHTML=`<div class="station-label">${s[1]} · ${related.length} 篇${m.role==='诗中地点'?' · 当前为诗中地点':''}</div><div class="station-links">${related.map(({v,i})=>`<button data-station-work="${i}" aria-pressed="${i===step}">${v[5]}</button>`).join('')}</div>`;document.querySelectorAll('[data-station-work]').forEach(el=>el.onclick=()=>select(+el.dataset.stationWork));
$('detail').innerHTML=`<div class="chapter">诗词里的这一站 · ${String(step+1).padStart(2,'0')}</div><div class="location"><h2>${s[1]}</h2><span>${s[4]}</span></div><p class="date">${s[0]} · ${m.role}</p>${scopeBadge(s)}${m.role!=='行迹'?`<p class="location-caution">${m.role==='地点待考'?'写作地点未确定，不绘制地图点。':'此点为诗中景物或他人所在地，不计入作者行迹。'}</p>`:''}<h3 class="poem-title">${s[5]}</h3><span class="poem-author">${person===2?'宋':'唐'} · ${p.name} · ${m.kind} · 全文</span><div class="poem ${m.kind==='散文'||m.kind==='赋'?'prose':''}">${s[6]}</div>${media()}<div class="story"><h4>▱ 诗文背后的故事</h4><p>${s[8]}</p></div><div class="study-focus"><h4>赏读与复习</h4><p>${m.focus}</p><small>${m.dateNote||'采用通行系年；位置为相关区域示意。'}</small></div>${lessonCTA(m.id)}<div class="detail-actions"><button id="fullRead">全文赏读 ↗</button><button id="discuss">✧ 课堂提问</button><button id="next">${step===p.stops.length-1?'回到首篇 ↺':'下一篇 →'}</button></div>`;
if($('photoTab'))$('photoTab').onclick=()=>{mediaMode='photo';render()};if($('filmTab'))$('filmTab').onclick=()=>{mediaMode='film';render()};if($('enlargePhoto')){$('enlargePhoto').onclick=enlargePhoto;$('enlargePhoto').querySelector('img').onerror=()=>{$('enlargePhoto').innerHTML='<span>照片暂未加载，请稍后重试。</span>';};}if($('detailFilm'))$('detailFilm').onclick=()=>playFilm($('detailFilm').dataset.film);bindLessonButtons();$('fullRead').onclick=()=>readWork(m.id);$('discuss').onclick=question;$('next').onclick=()=>select((step+1)%p.stops.length);drawMap();}
function stop(){clearInterval(timer);timer=null;$('play').textContent='▶';$('play').setAttribute('aria-label','播放足迹')}
function select(n){stop();step=n;mediaMode="film";render()}
function question(){const s=people[person].stops[step];showModal(`<p class="eyebrow">课堂讨论 · ${s[1]}</p><h2>从诗句，走进人生</h2><p>《${s[5]}》</p><h3>${s[10]}</h3><ol><li>独立读诗，在原文中圈出支持你观点的词语。</li><li>两人交流，结合地图位置和时代背景解释。</li><li>用“我从……读出了……”分享你的理解。</li></ol><p>教师提示：鼓励多种有文本依据的解读。建议用时 3—5 分钟。</p>`)}
$('range').oninput=e=>select(+e.target.value);$('play').onclick=()=>{if(timer){stop();return}if(step===people[person].stops.length-1){step=0;render()}$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','暂停足迹');timer=setInterval(()=>{if(step<people[person].stops.length-1){step++;render()}else stop()},4200)};$('reset').onclick=()=>select(0);$('questionBtn').onclick=question;$('close').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').close()};$('sources').onclick=()=>showModal(`<p class="eyebrow">资料与说明</p><h2>循迹有据，读诗有源</h2><p>诗文为古代公版作品，赏读与提问为本演示编写。创作年代采用通行说；《望庐山瀑布》采用 755 年说，《黄鹤楼送孟浩然之广陵》标为约 730 年。不同注本可能有不同系年。</p><ul>${sources.map(([t,u])=>`<li><a href="${u}" target="_blank" rel="noopener noreferrer">${t} ↗</a></li>`).join('')}</ul><p>底图仅用于定位城市。未绘制历史边界，也不表示交通路线。实景照片来自维基共享资源，摄影者、拍摄日期及授权链接见照片下方。照片为现代拍摄，不代表当年原貌；未接入实时影像。朗诵影片以动态绘本复现诗意，画面由人工智能生成，配音为合成语音。</p>`);initMapView();initCinema();render();fetch('assets/china.json').then(r=>{if(!r.ok)throw Error('地图加载失败');return r.json()}).then(g=>{geo=g;drawMap()}).catch(()=>{$('mapQuote').textContent='底图暂不可用 · 仍可探索城市与诗词'});
function openWork(id){const w=allWorks.find(w=>w.meta.id===id);if(!w)return;stop();person=w.a;step=w.i;mediaMode="film";render();$('modal').close();$('detail').scrollIntoView({behavior:'smooth',block:'start'});}

const requestedWork=new URLSearchParams(location.search).get("work");if(requestedWork)openWork(requestedWork);
